from pathlib import Path
home = Path.home()
base_dirs = [home/".electrum", home/".config"/"electrum"]
wallet_dirs = []
for b in base_dirs:
    w = b/"wallets"
    if w.exists() and w.is_dir():
        wallet_dirs.append(w)

if not wallet_dirs:
    print("No 'wallets' subfolder found under standard Electrum dirs:")
    for b in base_dirs:
        print(" -", b)
else:
    for w in wallet_dirs:
        print(f"Wallet dir: {w}")
        for p in sorted(w.iterdir()):
            print(" -", p.name + ("/" if p.is_dir() else ""))
PY
